from taf.internal.bmc.interfaces.redfish import RedfishRm17, RedfishOe19, RedfishOe20, RedfishOe22


class BmcVersions(object):
    """
    Supported interface versions
    """
    redfish_rm_17 = RedfishRm17
    redfish_oe_19 = RedfishOe19
    redfish_oe_20 = RedfishOe20
    redfish_oe_22 = RedfishOe22


class BmcInterfaceNotSupported(Exception):
    pass


class BmcInterfaceParametersIncorrect(Exception):
    pass


class BmcClient(object):

    @classmethod
    def create_connection(cls, address, port, interface="redfish_rm_17", interface_parameters=None):
        """
        Facade that provides initialized object of desired BMC interface.
        This method automatically calls .login() method on chosen interface.
        So by default interface object returned should be logged in. Unless stated otherwise by the interface doc.

        Usage:
            >>> from taf.internal.bmc import BmcClient
            >>> rfish_interface = BmcClient.create_connection(
            >>>  address="127.0.0.1",
            >>>  port=443,
            >>>  interface="redfish_rm_17",
            >>>  interface_parameters={"username": "admin", "password": "pass"})
            >>> result_poweroff = rfish_interface.system.power_off_immediate()
            >>> result_poweroff.data
            >>> {u'System reset result': u'Success.'}
            >>> result_poweroff.status
            >>> 200
            >>> result_poweron = rfish_interface.system.power_on()
            >>> result_poweron.data
            >>> {u'System reset result': u'Success.'}
            >>> result_poweron.status
            >>> 200

        :param str address: Address of BMC endpoint device ie. ip address
        :param int port: Port on which interface is listening on.
        :param str interface: Name of BMC interface supported by client.BmcClient, see: client.BmcVersions
        :param dict interface_parameters: Aditional parameters accepted by desired interface.
        :return: Interface object
        :raises BmcInterfaceNotSupported: When interface name provided in 'interface', \
        parameter is not supported in BmcVersions
        :raises BmcInterfaceParametersIncorrect: When parameters provided in 'interface_parameters' \
        are not supported by chosen interface
        """
        interface_type = getattr(BmcVersions, interface, None)
        if not interface_type:
            raise BmcInterfaceNotSupported("Interface {} is not supported".format(interface))

        if interface_parameters is None:
            interface_parameters = {}

        if not isinstance(interface_parameters, dict):
            raise BmcInterfaceParametersIncorrect("Parameter interface_parameters should be a dictionary type")
        try:
            bmc_interface = interface_type(address=address, port=port, **interface_parameters)

        except TypeError as exception:
            raise BmcInterfaceParametersIncorrect(str(exception))

        bmc_interface.login()
        return bmc_interface
